spec_text:
---- MODULE W4Od15m4p1t1 ----
EXTENDS Integers, FiniteSets

Ids == {"i1", "i2", "i3"}
QCap == 2

VARIABLES admitted, queue, inflight, applied

vars == <<admitted, queue, inflight, applied>>

Init ==
    /\ admitted = {}
    /\ queue = {}
    /\ inflight = {}
    /\ applied = {}

Admit(id) ==
    /\ id \notin admitted
    /\ Cardinality(queue) < QCap
    /\ admitted' = admitted \cup {id}
    /\ queue' = queue \cup {id}
    /\ UNCHANGED <<inflight, applied>>

StartApply(id) ==
    /\ id \in queue
    /\ queue' = queue \ {id}
    /\ inflight' = inflight \cup {id}
    /\ UNCHANGED <<admitted, applied>>

CommitApply(id) ==
    /\ id \in inflight
    /\ inflight' = inflight \ {id}
    /\ applied' = applied \cup {id}
    /\ UNCHANGED <<admitted, queue>>

AbortApply(id) ==
    /\ id \in inflight
    /\ inflight' = inflight \ {id}
    /\ queue' = queue \cup {id}
    /\ UNCHANGED <<admitted, applied>>

Idle ==
    /\ applied = Ids
    /\ UNCHANGED vars

Next ==
    \/ \E id \in Ids : Admit(id)
    \/ \E id \in Ids : StartApply(id)
    \/ \E id \in Ids : CommitApply(id)
    \/ \E id \in Ids : AbortApply(id)
    \/ Idle

Spec == Init /\ [][Next]_vars

TypeOK ==
    /\ admitted \subseteq Ids
    /\ queue \subseteq Ids
    /\ inflight \subseteq Ids
    /\ applied \subseteq Ids

NoLostUpdates ==
    /\ admitted = (queue \cup inflight \cup applied)
    /\ queue \cap inflight = {}
    /\ queue \cap applied = {}
    /\ inflight \cap applied = {}

====
